$dir='docs\validation\data\owner-completion'
$rows=Get-Content -LiteralPath (Join-Path $dir 'target-evidence-inventory.jsonl')|Where-Object {$_.Trim()}|ForEach-Object {$_|ConvertFrom-Json}
$sourceNames=@{'alahsa-opportunities'='منصة الفرص الاستثمارية بالأحساء';'ahda'='هيئة تطوير الأحساء';'invest-saudi'='استثمر في السعودية';'ncp'='المركز الوطني للتخصيص'}
$reason=@{'alahsa-opportunities'='Raw source payload contains only listing metadata, land/activity/area/deadline details and taxonomy; no owner, issuer, agency, authority, or responsible entity field.';'ahda'='Raw payload has no structured owner field; named ministries/funds in narrative are support, funding, or sector-enablement mentions, not clear owner/responsible phrasing.';'invest-saudi'='No raw owner, agency, company, or responsible entity field. backed_by is blank; contact_details and inner_data are empty. Arabic Ministry of Investment value exists only in the unsafe adapter owner projection, not raw item evidence. Descriptions mention operator/investor roles.';'ncp'='Raw project_owner candidate is “the Ministry of Municipalities”, while article says MOMAH and NCP announced an EOI and describes operation across five municipalities. Owner/grantor vs publisher/announcer and the municipal role remain ambiguous; retain existing review.'}
$classified=foreach($m in $rows){$s=@($m.sources);$src=$s[0];$review=([int]$m.master_id -eq 228);[pscustomobject]@{master_id=$m.master_id;canonical_id=$m.canonical_id;title=$m.title;current_owner_display='غير محدد';owner_is_null=($null -eq $m.current_owner -or [string]::IsNullOrWhiteSpace([string]$m.current_owner));classification=if($review){'REVIEW_REQUIRED'}else{'CORRECTLY_RETAINED_UNSPECIFIED'};source_key=$src.source_key;source_name=$sourceNames[$src.source_key];source_record_id=$src.source_record_id;external_id=$src.external_id;source_owner_projection=$src.source_owner;raw_evidence_summary=$reason[$src.source_key]}}
$classified|Export-Csv -LiteralPath (Join-Path $dir 'target-owner-classification.csv') -NoTypeInformation -Encoding utf8
$rows|ForEach-Object {$_.master_id}|Set-Content -LiteralPath (Join-Path $dir 'target-master-ids.txt') -Encoding utf8
$dist=foreach($src in @('alahsa-opportunities','ahda','invest-saudi','ncp')){$subset=@($classified|Where-Object {$_.source_key -eq $src});[pscustomobject]@{source_key=$src;source=$sourceNames[$src];target_masters=$subset.Count;master_ids=($subset.master_id -join ',');resolved_explicit=0;resolved_cross_source=0;correctly_retained_unspecified=@($subset|Where-Object {$_.classification -eq 'CORRECTLY_RETAINED_UNSPECIFIED'}).Count;review_required=@($subset|Where-Object {$_.classification -eq 'REVIEW_REQUIRED'}).Count;owner_fields_and_notes=$reason[$src]}}
$dist|Export-Csv -LiteralPath (Join-Path $dir 'target-source-distribution.csv') -NoTypeInformation -Encoding utf8
$summary=[pscustomobject]@{snapshot_at=(Get-Content -Raw (Join-Path $dir 'start-snapshot.json')|ConvertFrom-Json).snapshot_at;target_count=$rows.Count;target_source_links=($rows|Measure-Object -Property { @($_.sources).Count } -Sum).Sum;target_ids=(@($rows.master_id));resolved_explicit=0;resolved_cross_source=0;correctly_retained_unspecified=@($classified|Where-Object {$_.classification -eq 'CORRECTLY_RETAINED_UNSPECIFIED'}).Count;review_required=@($classified|Where-Object {$_.classification -eq 'REVIEW_REQUIRED'}).Count;review_ids=@($classified|Where-Object {$_.classification -eq 'REVIEW_REQUIRED'}|ForEach-Object {[int]$_.master_id});owner_corrections=0;new_canonical_owners=0}
$summary|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $dir 'evidence-audit-summary.json') -Encoding utf8
"target=$($rows.Count);source_links=$((@($rows|% {@($_.sources).Count}|Measure-Object -Sum).Sum));explicit=0;cross=0;retained=$($summary.correctly_retained_unspecified);review=$($summary.review_required);source_categories=$($dist|%{"$($_.source_key):$($_.target_masters)"}-join ',')"
